 * @param {string | ((p: object) => string)} schluessel Pfad ohne Präfix (bei [slug]-Routen aus params)
 * @param {object | ((land: string|null, p: object) => object|Promise<object>)} basis
 */
export function seitenMetadata(schluessel, basis) {
  return async function generateMetadata({ params }) {
    const p = (await params) || {};
    const land = p.land !== undefined ? landAusPraefix(p.land) : null;
    const konkret = typeof schluessel === "function" ? schluessel(p) : schluessel;
    const b = (typeof basis === "function" ? await basis(land, p) : basis) || {};
    const a = alternates(konkret, land, { languages: b.alternates?.languages });
    const index = land ? indexierbar(konkret, land) : null;
    return {
      ...b,
      alternates: { ...(b.alternates || {}), ...a, ...(a.languages ? {} : { languages: undefined }) },
      ...(b.openGraph ? { openGraph: { ...b.openGraph, url: a.canonical, ...(land ? { locale: ogLocale(land) } : {}) } } : {}),
      ...(land && !index ? { robots: { index: false, follow: true } } : {}),
    };
  };
}
