import { LandHinweis } from "@/components/Land/LandHinweis";
import { FREIFLAECHE_CH } from "@/data/laender/ch/freiflaeche";
import { chTexte } from "@/data/laender/ch/schreibung";

const PFAD = pfad("/freiflaeche");
const TITEL = "Freiflächen-PV & Solarparks entwickeln | ÖkoInvest";
const BESCHREIBUNG =
  "Solarparks ab rund 3 Hektar in DE, AT und CH: Flächenkriterien, EEG-Flächenkulisse, Genehmigung, Ökologie, Rückbau und Zeitplan. Jetzt Fläche prüfen.";

const metadata = {
  title: TITEL,
  description: BESCHREIBUNG,
  alternates: { canonical: abs(PFAD) },
  openGraph: {
    type: "website",
    locale: "de_DE",
    url: abs(PFAD),
    siteName: "ÖkoInvest",
    title: TITEL,
    description: BESCHREIBUNG,
    images: [{ url: abs("/img/solarpark-himmel.jpg"), width: 1280, height: 852, alt: "Solarpark unter blauem Himmel" }],
  },
};

// Länderinhalte (Ländermodell): gemeinsam = Stand vor Welle 2; CH = src/data/laender/ch/freiflaeche.js
const INHALT = { gemeinsam: {}, CH: FREIFLAECHE_CH };

const metadataFuer = (land) =>
  land === "CH"
    ? {
        ...metadata,
        title: "Freiflächen-PV in der Schweiz: Art. 24ter RPG & Bewilligung | ÖkoInvest",
        description: "Solarpark in der Schweiz: wann Freiflächen-PV und Agri-PV ausserhalb der Bauzone standortgebunden sind (Art. 24ter RPG), Bewilligung, HEIV-Auktion und Solarexpress.",
        openGraph: { ...metadata.openGraph, locale: "de_CH", title: "Freiflächen-PV in der Schweiz | ÖkoInvest", description: "Art. 24ter RPG, Bewilligung durch Gemeinde und Kanton, HEIV-Auktion und Solarexpress im Überblick." },
      }
    : metadata;

const mwpBei = (ha) => ha / FREIFLAECHE.haProMwp;

/** Querverweise CH: ohne Pachtrechner und deutsche Ratgeber (Bebauungsplan, Rückbaubürgschaft) */
const querverweiseCh = (t) => [
  t.querverweisRegion,
  { href: "/ratgeber/freiflaechen-pv-schweiz", titel: "Freiflächen-PV in der Schweiz", text: "Raumplanungsrecht, Agri-PV und Solarexpress ausführlich erklärt." },
  { href: "/flaechencheck", titel: "Flächencheck", text: t.querverweise["/flaechencheck"] },
  { href: "/agri-pv", titel: "Agri-PV", text: t.querverweise["/agri-pv"] },
  { href: "/prozess", titel: "Unser Prozess", text: "Wie wir Projekte Schritt für Schritt zur Baureife bringen." },
];

/** Genehmigungskarten: Land der Seite zuerst, CH-Karte mit geprüften Punkten (Länderinhalt), Schweizer Schreibweise */
const verfahren = (karten, t, land) => {
