export const AGRI_PV_AT = {
  heroPunkte: ["Geplant nach DIN SPEC 91434 – Kategorie I & II", "Ohne EAG-Abschlag nach § 33 EAG", "Widmung nach Landesrecht geprüft", "Rahmen für Österreich, Deutschland und Schweiz"],
