const TITEL = "Dachfläche für Photovoltaik verpachten | ÖkoInvest";
const BESCHREIBUNG =
  "Gewerbe-, Hallen-, Agrar- oder Logistikdach ab 1.000 m² für PV verpachten: Pachtmodelle, Dachstrom, Sanierung, Vertrag, Steuern und Ablauf – kostenfrei.";

const metadata = {
